const SPLIT_LEDGER_KEY="citypulsex.split-ledger.v1";
const state={view:"home",splitExpenses:[],splitPeople:["Friend 1","Friend 2","Friend 3","Friend 4"],splitAvatars:{},splitCharacters:{},sharedTripCode:"",sharedTripName:"",sharedTripUpdatedAt:"",sharedTripEditorToken:"",companion:"Bloop",emoji:"🐙",budget:10000,days:4,origin:"New Delhi, India",destination:"Goa, India",priority:"balanced",selectedRoute:1,saved:[],layers:{places:true,transport:true,weather:false,experiences:true},map:null,markers:[],routeLayer:null};
function restoreSplitLedger(){
 try{
  const raw=window.localStorage.getItem(SPLIT_LEDGER_KEY);if(!raw)return;
  const data=JSON.parse(raw);const people=Array.isArray(data.people)?data.people.map(x=>String(x||"").trim()).slice(0,12):[];
  if(people.length>=1&&people.every(Boolean)&&new Set(people.map(x=>x.toLowerCase())).size===people.length){
   state.splitPeople=people;state.sharedTripCode=typeof data.sharedTripCode==="string"?data.sharedTripCode:"";state.sharedTripName=typeof data.sharedTripName==="string"?data.sharedTripName:"";state.sharedTripUpdatedAt=typeof data.sharedTripUpdatedAt==="string"?data.sharedTripUpdatedAt:"";state.splitAvatars=(data.avatars&&typeof data.avatars==="object"&&!Array.isArray(data.avatars))?Object.fromEntries(Object.entries(data.avatars).filter(([name,url])=>people.includes(name)&&typeof url==="string"&&url.startsWith("data:image/")&&url.length<180000)):{};state.splitCharacters=(data.characters&&typeof data.characters==="object"&&!Array.isArray(data.characters))?Object.fromEntries(Object.entries(data.characters).filter(([name,id])=>people.includes(name)&&typeof id==="string")):{};const allowed=new Set(people);
   state.splitExpenses=(Array.isArray(data.expenses)?data.expenses:[]).filter(e=>e&&allowed.has(e.paidBy)&&Number.isFinite(Number(e.amount))&&Number(e.amount)>0&&Array.isArray(e.splitWith)).map(e=>({id:String(e.id||`${Date.now()}-${Math.random()}`),description:String(e.description||"Expense").slice(0,100),amount:Math.round(Number(e.amount)*100)/100,paidBy:e.paidBy,splitWith:e.splitWith.filter(p=>allowed.has(p)).filter((p,i,a)=>a.indexOf(p)===i),createdAt:String(e.createdAt||new Date().toISOString())})).filter(e=>e.splitWith.length>0);
  }
 }catch(_error){/* Keep a clean in-memory ledger if storage is unavailable or malformed. */}
}
function saveSplitLedger(){try{window.localStorage.setItem(SPLIT_LEDGER_KEY,JSON.stringify({version:5,people:state.splitPeople,expenses:state.splitExpenses,avatars:state.splitAvatars||{},characters:state.splitCharacters||{},sharedTripCode:state.sharedTripCode||"",sharedTripName:state.sharedTripName||"",sharedTripUpdatedAt:state.sharedTripUpdatedAt||""}));return true;}catch(_error){return false;}}
restoreSplitLedger();
try{state.sharedTripEditorToken=sessionStorage.getItem("citypulsex.shared-trip-editor-token")||"";}catch(_){}
const buddies=[{name:"Bloop",emoji:"🐙",kind:"Plush octopus explorer",desc:"A soft 3D sea-sprite who greets you, walks between portals and helps plan adventures.",voice:"Hi hi! I’m Bloop. Want to wander somewhere wonderful?"},{name:"Sprout",emoji:"🌱",kind:"Original forest spirit",desc:"Playful, curious and always ready to celebrate a discovery.",voice:"Hello explorer! Where shall we wander today?"},{name:"Pip",emoji:"🐧",kind:"Polar penguin",desc:"A curious polar guide for wildlife, icy landscapes and science.",voice:"Flipper high-five! Let's explore somewhere extraordinary."},{name:"Roo",emoji:"🦘",kind:"Outback adventurer",desc:"Energetic, outdoorsy and full of adventurous ideas.",voice:"Hop to it! Let's find your next adventure."},{name:"Mira",emoji:"🦚",kind:"Culture and colour guide",desc:"A thoughtful guide to heritage, food, festivals and art.",voice:"Every place has a story. Shall we discover one?"},{name:"Orbit",emoji:"🪐",kind:"Cosmic explorer",desc:"A space-loving guide to geography, maps and the planet.",voice:"Coordinates set. Curiosity engines online!"},{name:"Paws",emoji:"🦊",kind:"Woodland companion",desc:"A clever, witty companion who loves hidden gems.",voice:"Psst. I know a few hidden gems. Want in?"}];
try{const savedBuddy=localStorage.getItem("citypulsex.companion");const activeBuddy=buddies.find(item=>item.name===savedBuddy);if(activeBuddy){state.companion=activeBuddy.name;state.emoji=activeBuddy.emoji;}else{state.companion="Bloop";state.emoji="🐙";}}catch(_){}
