const friendCharacterLibrary=window.CityPulseFriendCharacters;
function ensureUniqueFriendCharacters(){
 if(!friendCharacterLibrary)return;
 state.splitCharacters=friendCharacterLibrary.normalize(state.splitPeople,state.splitCharacters||{});
}
ensureUniqueFriendCharacters();
function splitAvatarMarkup(person,index){
 const uploaded=state.splitAvatars?.[person];
 const characterId=state.splitCharacters?.[person]||friendCharacterLibrary?.defaultForIndex(index)||"pikachu";
 const character=friendCharacterLibrary?.get(characterId);
 const src=uploaded||character?.src||"assets/companions/bloop-mini.svg";
 const alt=uploaded?`${person} profile photo`:`${person} ${character?.name||"travel character"} avatar`;
 const fallback="assets/companions/bloop-mini.svg";
 return `<span class="split-avatar ${uploaded?"has-photo":"has-character"}" data-character-id="${escapeHtml(characterId)}" style="--character-scene-image:url('${escapeHtml(src)}')"><img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}" title="${escapeHtml(character?.name||"Traveller")}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='${fallback}'"></span>`;
}
function friendCharacterPickerMarkup(){return `<div class="friend-character-backdrop" id="friendCharacterBackdrop" hidden><section class="friend-character-dialog" role="dialog" aria-modal="true" aria-labelledby="friendCharacterTitle"><div class="friend-character-dialog-head"><div><div class="eyebrow">MAKE YOUR CREW YOURS</div><h2 id="friendCharacterTitle">Choose a character</h2><p id="friendCharacterSubtitle">Every friend gets a different character. Characters already chosen by someone else are locked.</p></div><button type="button" id="closeFriendCharacterPicker" class="friend-character-close" aria-label="Close character picker">×</button></div><div class="friend-character-grid" id="friendCharacterGrid"></div><div class="friend-character-dialog-foot"><span>✦ Animated idle motion · hover to see them react</span><button type="button" id="cancelFriendCharacterPicker" class="secondary-btn">Done</button></div></section></div>`}
function openFriendCharacterPicker(person){
 const backdrop=$("#friendCharacterBackdrop"),grid=$("#friendCharacterGrid");if(!backdrop||!grid||!friendCharacterLibrary)return;
 const selected=state.splitCharacters?.[person];
 const usedByOther=Object.fromEntries(Object.entries(state.splitCharacters||{}).filter(([name,id])=>name!==person&&state.splitPeople.includes(name)).map(([name,id])=>[id,name]));
 $("#friendCharacterTitle").textContent=`Choose a character for ${person}`;
 $("#friendCharacterSubtitle").textContent="Choose one of the characters below. A character can belong to only one friend in this trip.";
 grid.innerHTML=friendCharacterLibrary.characters.map(character=>{
  const assigned=usedByOther[character.id];
  const locked=Boolean(assigned);
  const isSelected=selected===character.id;
  const label=locked?`In use by ${escapeHtml(assigned)}`:isSelected?"Current character":escapeHtml(character.category);
  const badge=locked?'<span class="character-locked">IN USE</span>':isSelected?'<span class="character-current">SELECTED</span>':'';
  const buttonClass=isSelected?"friend-character-choice is-selected":"friend-character-choice";
  const disabled=locked?"disabled":"";
  return `<button type="button" class="${buttonClass}" data-character-choice="${escapeHtml(character.id)}" ${disabled} aria-pressed="${isSelected}"><span class="friend-character-choice-art" data-character-id="${escapeHtml(character.id)}" style="--character-scene-image:url('${escapeHtml(character.src)}')"><img src="${escapeHtml(character.src)}" alt="${escapeHtml(character.name)} animated scene" loading="lazy" decoding="async"><i aria-hidden="true">✦</i></span><strong>${escapeHtml(character.name)}</strong><small>${label}</small>${badge}</button>`;
 }).join("");
 backdrop.hidden=false;document.body.classList.add("character-picker-open");$("#closeFriendCharacterPicker")?.focus();
 backdrop.dataset.person=person;
}
function closeFriendCharacterPicker(){const backdrop=$("#friendCharacterBackdrop");if(backdrop){backdrop.hidden=true;document.body.classList.remove("character-picker-open");}}
function companionSlug(name){return ({Bloop:"bloop",Sprout:"sprout",Pip:"pip",Roo:"roo",Mira:"mira",Orbit:"orbit",Paws:"paws"})[name]||"bloop"}
const routes=[{icon:"🚇",name:"Transit + walk",desc:"One transfer · moderate walking · sample estimate",time:"34 min",cost:55,tag:"LOW COST"},{icon:"🛺",name:"Auto / ride-hail",desc:"Direct route · fewer transfers · sample estimate",time:"22 min",cost:180,tag:"CONVENIENT"},{icon:"🚲",name:"Cycle + walk",desc:"Outdoor route · check local availability",time:"31 min",cost:35,tag:"ACTIVE"}];
