 planner:{eyebrow:"TRIP STUDIO · DREAM IT, SHAPE IT",tag:"YOUR NEXT CHAPTER",title:"A little plan. A lot of possibility.",copy:"Move from a daydream to a route, a rhythm and a budget that feels right.",scenes:[{name:"Goa, India",src:"assets/destinations/goa.webp",note:"SUNLIT DAYS · EASY ESCAPES"},{name:"Kyoto, Japan",src:"assets/destinations/kyoto.webp",note:"QUIET LANES · CULTURE"},{name:"Bali, Indonesia",src:"assets/destinations/india-inspiration.webp",note:"GREEN HORIZONS · ISLAND TIME"}]},
