function wireBloopDock(){const launcher=$("#bloopLauncher"),panel=$("#heroGuideChat"),close=$("#heroGuideClose"),form=$("#heroGuideForm"),svg=$("#bloopMiniArt");if(!launcher||launcher.dataset.wired==="1")return;launcher.dataset.wired="1";const pupils=svg?.querySelectorAll(".bloop-pupil")||[];let blinkTimer=null;const blink=()=>{launcher.classList.remove("is-blinking");void launcher.offsetWidth;launcher.classList.add("is-blinking");clearTimeout(blinkTimer);blinkTimer=setTimeout(()=>launcher.classList.remove("is-blinking"),240);};const moveEyes=(x,y)=>pupils.forEach(p=>p.setAttribute("transform",`translate(${x.toFixed(2)} ${y.toFixed(2)})`));const open=()=>{panel.hidden=false;launcher.setAttribute("aria-expanded","true");launcher.classList.add("is-chat-open");blink();$("#heroGuideInput")?.focus();};const shut=()=>{panel.hidden=true;launcher.setAttribute("aria-expanded","false");launcher.classList.remove("is-chat-open");};launcher.addEventListener("click",()=>{if(panel.hidden){moveEyes(-1.8,-1.2);open();window.setTimeout(()=>moveEyes(0,0),650);}else{shut();moveEyes(0,0);}});close?.addEventListener("click",shut);form?.addEventListener("submit",sendHeroGuideMessage);$$('[data-guide-prompt]').forEach(b=>b.addEventListener('click',()=>{const input=$("#heroGuideInput");if(input){input.value=b.dataset.guidePrompt;sendHeroGuideMessage(new Event("submit"));}}));launcher.addEventListener("pointermove",e=>{const r=launcher.getBoundingClientRect(),dx=(e.clientX-(r.left+r.width/2))/(r.width/2),dy=(e.clientY-(r.top+r.height/2))/(r.height/2);moveEyes(Math.max(-2.5,Math.min(2.5,dx*2.5)),Math.max(-1.9,Math.min(1.9,dy*1.9)));});launcher.addEventListener("pointerleave",()=>moveEyes(0,0));launcher.addEventListener("focus",()=>moveEyes(1.1,-.3));launcher.addEventListener("blur",()=>moveEyes(0,0));window.setInterval(blink,5200);}
