 async function createSharedTrip(){const button=$("#createSharedTrip");if(button)button.disabled=true;try{const name=prompt("Name this shared trip",state.sharedTripName||"Our TRAVESÍA trip");if(name===null)return;const payload=await getJSON("/api/shared-trips",{method:"POST",body:JSON.stringify({name,state:currentSharedState()})});state.sharedTripCode=payload.share_code;state.sharedTripEditorToken=payload.editor_token||"";try{sessionStorage.setItem("citypulsex.shared-trip-editor-token",state.sharedTripEditorToken);}catch(_){}state.sharedTripName=payload.name;state.sharedTripUpdatedAt=payload.updated_at;saveSplitLedger();renderView();toast("Trip created. Read code and editor token are separate; the editor token is shown only once.");}catch(error){toast(error.message||"Could not create a shared trip.");}finally{if(button?.isConnected)button.disabled=false;}}
 async function loadSharedTrip(code,confirmReplace=true){const trimmed=String(code||"").trim().toUpperCase();if(!trimmed){toast("Enter a shared trip code first.");return;}if(confirmReplace&&state.splitExpenses.length&&!confirm("Load the shared trip and replace the expenses currently shown on this device?"))return;try{const edit=prompt("Editor token from the trip owner (leave blank for read-only access):","");if(edit===null)return;state.sharedTripEditorToken=edit.trim();try{if(state.sharedTripEditorToken)sessionStorage.setItem("citypulsex.shared-trip-editor-token",state.sharedTripEditorToken);else sessionStorage.removeItem("citypulsex.shared-trip-editor-token");}catch(_){}const payload=await getJSON(`/api/shared-trips/${encodeURIComponent(trimmed)}`);state.sharedTripCode=trimmed;setSharedState(payload);renderView();toast(state.sharedTripEditorToken?`Loaded ${state.sharedTripName} with editor access.`:`Loaded ${state.sharedTripName} in read-only sync mode.`);}catch(error){toast(error.message||"Could not load that shared trip.");}}
 async function pushSharedTrip(){if(!state.sharedTripCode)return;if(!state.sharedTripEditorToken){const status=$("#sharedTripStatus");if(status)status.textContent="Read-only invite: an editor token is required to sync changes. Your local edits have not been shared.";return;}try{const payload=await getJSON(`/api/shared-trips/${encodeURIComponent(state.sharedTripCode)}`,{method:"PUT",headers:{"X-Shared-Trip-Editor":state.sharedTripEditorToken},body:JSON.stringify({state:currentSharedState(),expected_updated_at:state.sharedTripUpdatedAt})});state.sharedTripUpdatedAt=payload.updated_at;saveSplitLedger();const status=$("#sharedTripStatus");if(status)status.textContent=`Synced · ${new Date(payload.updated_at).toLocaleTimeString()}`;}catch(error){const status=$("#sharedTripStatus");if(status)status.textContent=`Sync issue: ${error.message}`;}}
 function scheduleSharedTripSync(){clearTimeout(window.cityPulseSharedTripSyncTimer);window.cityPulseSharedTripSyncTimer=setTimeout(pushSharedTrip,500);}
 if($("#createSharedTrip"))$("#createSharedTrip").addEventListener("click",createSharedTrip);
 if($("#joinSharedTrip"))$("#joinSharedTrip").addEventListener("click",()=>loadSharedTrip($("#joinSharedTripCode").value));
 if($("#refreshSharedTrip"))$("#refreshSharedTrip").addEventListener("click",()=>loadSharedTrip(state.sharedTripCode,true));
 if($("#addSplitPerson"))$("#addSplitPerson").addEventListener("click",()=>{
  const name=window.CityPulseExpenseLedger.createNextMemberName(state.splitPeople);
  if(!name){toast("This trip supports up to 12 people in the current version.");return;}
  state.splitPeople.push(name);ensureUniqueFriendCharacters();persist();renderView();toast(`${name} added with a unique character. Choose another one any time.`);
 });
 $$(".remove-split-person").forEach(button=>button.addEventListener("click",()=>{
  const index=Number(button.dataset.removePerson),removed=state.splitPeople[index];if(!removed||state.splitPeople.length<=1)return;
  const remaining=state.splitPeople.filter(person=>person!==removed);const paidExpenses=state.splitExpenses.filter(expense=>expense.paidBy===removed);
  let replacement=null;
  if(paidExpenses.length){replacement=prompt(`${removed} is recorded as paying for ${paidExpenses.length} expense(s). To keep those amounts in the settlement, enter the current friend's name who should take over these payer records:
${remaining.join(", ")}

Cancel to keep ${removed} in the trip.`,remaining[0]);if(replacement===null)return;replacement=replacement.trim();if(!remaining.some(person=>person.toLowerCase()===replacement.toLowerCase())){toast("Choose one of the remaining friend names exactly, or cancel removal.");return;}replacement=remaining.find(person=>person.toLowerCase()===replacement.toLowerCase());}
  const associated=state.splitExpenses.filter(expense=>expense.paidBy===removed||expense.splitWith.includes(removed)).length;
  if(!confirm(`Remove ${removed} from this trip?${paidExpenses.length?` ${paidExpenses.length} payer record(s) will be reassigned to ${replacement}.`:""} ${associated-paidExpenses.length>0?"Their share will be removed from expense splits and balances recalculated.":""}`))return;
  try{
   const revised=window.CityPulseExpenseLedger.removeMember(state.splitPeople,state.splitExpenses,removed,replacement);
   state.splitExpenses=revised.expenses;state.splitPeople=revised.people;
  }catch(error){toast(error.message||"Could not remove this friend safely.");return;}
  delete state.splitAvatars?.[removed];delete state.splitCharacters?.[removed];ensureUniqueFriendCharacters();persist();renderView();toast(`${removed} removed. Their character is available for another friend.`);
 }));
 if($("#copySharedTripCode"))$("#copySharedTripCode").addEventListener("click",async()=>{const text=`Join my TRAVESÍA trip: ${state.sharedTripName||"Shared trip"}\nRead-only trip code: ${state.sharedTripCode}${state.sharedTripEditorToken?`\nEditor token (write access): ${state.sharedTripEditorToken}`:"\nAsk the trip owner for a separate editor token if you need write access."}`;try{await navigator.clipboard.writeText(text);toast("Invite copied. Treat the editor token like a password.");}catch(_){prompt("Copy this private trip invite",text);}});
 $$("[data-pick-character]").forEach(button=>button.addEventListener("click",()=>openFriendCharacterPicker(button.dataset.pickCharacter)));
 const characterBackdrop=$("#friendCharacterBackdrop"),characterGrid=$("#friendCharacterGrid");
 const closeCharacterPicker=()=>closeFriendCharacterPicker();
 $("#closeFriendCharacterPicker")?.addEventListener("click",closeCharacterPicker);$("#cancelFriendCharacterPicker")?.addEventListener("click",closeCharacterPicker);
 characterBackdrop?.addEventListener("click",event=>{if(event.target===characterBackdrop)closeCharacterPicker()});
 if(!window.cityPulseFriendPickerEscapeWired){document.addEventListener("keydown",event=>{const activeBackdrop=$("#friendCharacterBackdrop");if(event.key==="Escape"&&activeBackdrop&&!activeBackdrop.hidden)closeFriendCharacterPicker();});window.cityPulseFriendPickerEscapeWired=true;}
 characterGrid?.addEventListener("click",event=>{const choice=event.target.closest("[data-character-choice]");if(!choice||choice.disabled)return;const person=characterBackdrop.dataset.person,id=choice.dataset.characterChoice;if(!state.splitPeople.includes(person))return;const assigned=Object.entries(state.splitCharacters||{}).find(([name,value])=>name!==person&&state.splitPeople.includes(name)&&value===id);if(assigned){toast(`${friendCharacterLibrary.get(id)?.name||"That character"} is already used by ${assigned[0]}. Choose a different one.`);return;}state.splitCharacters[person]=id;delete state.splitAvatars?.[person];persist();closeCharacterPicker();renderView();toast(`${friendCharacterLibrary.get(id)?.name||"Character"} assigned to ${person}. No duplicates in this crew.`)});
 $$(".friend-avatar-file").forEach(input=>input.addEventListener("change",async()=>{const file=input.files?.[0];if(!file)return;if(!file.type.startsWith("image/")){toast("Choose an image file for the friend portrait.");return;}try{const idx=Number(input.dataset.avatarIndex),person=state.splitPeople[idx];const data=await compressFriendAvatar(file);state.splitAvatars=state.splitAvatars||{};state.splitAvatars[person]=data;persist();renderView();toast(`Photo saved for ${person}.`);}catch(error){toast(error.message||"Photo upload failed.");}}));
 $$(".split-person-name").forEach(input=>input.addEventListener("change",()=>{
  const idx=Number(input.dataset.index),old=state.splitPeople[idx],name=input.value.trim()||`Friend ${idx+1}`;
  if(state.splitPeople.some((p,i)=>i!==idx&&p.toLowerCase()===name.toLowerCase())){toast("Each friend needs a different name.");input.value=old;return;}
  state.splitPeople[idx]=name;if(state.splitAvatars?.[old]){state.splitAvatars[name]=state.splitAvatars[old];delete state.splitAvatars[old];}if(state.splitCharacters?.[old]){state.splitCharacters[name]=state.splitCharacters[old];delete state.splitCharacters[old];}state.splitExpenses.forEach(e=>{if(e.paidBy===old)e.paidBy=name;e.splitWith=e.splitWith.map(p=>p===old?name:p);});persist();renderView();
 }));
 const splitSelect=$("#expenseSplit"),customPanel=$("#expenseSplitCustom");
 splitSelect.addEventListener("change",()=>{customPanel.hidden=splitSelect.value!=="custom";});
 $$("[data-split-member]").forEach(input=>input.addEventListener("change",()=>{if(!$$('[data-split-member]:checked').length){input.checked=true;toast("Select at least one friend to share the expense.");}}));
 $("#splitForm").addEventListener("submit",e=>{
  e.preventDefault();const rawAmount=Number($("#expenseAmount").value),amount=Math.round(rawAmount*100)/100;
  if(!Number.isFinite(amount)||amount<=0){toast("Enter an amount greater than zero.");return;}
  const payer=$("#expensePayer").value,choice=splitSelect.value;let splitWith;
  if(choice==="all")splitWith=[...state.splitPeople];
  else if(choice.startsWith("except:")){const excluded=state.splitPeople[Number(choice.split(":")[1])];splitWith=state.splitPeople.filter(p=>p!==excluded);}
  else splitWith=$$('[data-split-member]:checked').map(input=>state.splitPeople[Number(input.dataset.splitMember)]);
  if(!splitWith.length){toast("Select at least one person to share the expense.");return;}
  state.splitExpenses.push({id:`${Date.now()}-${Math.random().toString(36).slice(2,8)}`,description:$("#expenseDesc").value.trim(),amount,paidBy:payer,splitWith,createdAt:new Date().toISOString()});
  persist();renderView();toast("Expense saved. Shares and who-pays-whom have been recalculated.");
 });
 $("#clearExpenses").addEventListener("click",()=>{if(state.splitExpenses.length&&confirm("Clear all expenses for this trip? This cannot be undone.")){state.splitExpenses=[];persist();renderView();toast("Trip ledger cleared.");}});
 $$(".delete-expense").forEach(b=>b.addEventListener("click",()=>{state.splitExpenses=state.splitExpenses.filter(e=>String(e.id)!==b.dataset.id);persist();renderView();toast("Expense removed and balances recalculated.");}));
 $("#exportExpenses").addEventListener("click",()=>{
  const quote=v=>'"'+String(v??"").replace(/"/g,'""')+'"';
  const rows=[["record_type","expense","paid_by","split_between","amount_inr","date"]];
  state.splitExpenses.forEach(e=>rows.push(["expense",e.description,e.paidBy,e.splitWith.join("; "),Number(e.amount).toFixed(2),e.createdAt]));
  const people=state.splitPeople,owed=Object.fromEntries(people.map(p=>[p,0])),paid=Object.fromEntries(people.map(p=>[p,0]));
  state.splitExpenses.forEach(e=>{const cents=Math.round(Number(e.amount)*100);paid[e.paidBy]=(paid[e.paidBy]||0)+cents;const participants=e.splitWith.filter(p=>p in owed);if(!participants.length)return;const base=Math.floor(cents/participants.length),rem=cents%participants.length;participants.forEach((p,i)=>owed[p]+=base+(i<rem?1:0));});
  const creditors=people.map(p=>({p,amt:paid[p]-owed[p]})).filter(x=>x.amt>0),debtors=people.map(p=>({p,amt:owed[p]-paid[p]})).filter(x=>x.amt>0);let di=0,ci=0;
  while(di<debtors.length&&ci<creditors.length){const cents=Math.min(debtors[di].amt,creditors[ci].amt);rows.push(["settlement",`${debtors[di].p} pays ${creditors[ci].p}`,debtors[di].p,creditors[ci].p,(cents/100).toFixed(2),""]);debtors[di].amt-=cents;creditors[ci].amt-=cents;if(!debtors[di].amt)di++;if(!creditors[ci].amt)ci++;}
  const csv="\uFEFF"+rows.map(row=>row.map(quote).join(",")).join("\r\n"),blob=new Blob([csv],{type:"text/csv;charset=utf-8;"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="citypulsex-trip-expenses.csv";document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast("Expense ledger downloaded as CSV.");
 });
 $("#copySettlements").addEventListener("click",async()=>{
  const rows=$$(".settle-transfer").map(row=>row.innerText.replace(/\s+/g," ").trim()),text=rows.length?rows.join("\n"):"Everyone is settled up.";
  try{await navigator.clipboard.writeText(text);toast("Settlement instructions copied.");}catch(_error){window.prompt("Copy settlement instructions:",text);}
 });
